// React component with modals for all services
// You can integrate this into your existing Services.js

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

export default function Services() {
  const [activeModal, setActiveModal] = useState(null);

  const services = [
    {
      id: "audit",
      title: "Audit and Attest Services",
      content: (
        <div className="space-y-4 text-gray-700 leading-relaxed">
          <h2 className="text-xl font-semibold">Full Audit Services</h2>
          <ul className="list-disc pl-6 space-y-1">
            <li>Walkthroughs of Key Processes</li>
            <li>Risk Assessment Procedures</li>
            <li>Substantive Testing</li>
            <li>Preparation of Financial Statements</li>
          </ul>
          <p>
            We tailor our audit approach to your organization’s size, complexity, and
            industry to deliver meaningful results.
          </p>

          <h2 className="text-xl font-semibold pt-4">Attest Services</h2>
          <ul className="list-disc pl-6 space-y-1">
            <li>Review Engagements</li>
            <li>Agreed-Upon Procedures</li>
            <li>Compilation Services</li>
          </ul>
        </div>
      )
    },

    {
      id: "bookkeeping",
      title: "Accounting & Bookkeeping Services",
      content: (
        <div className="space-y-4 text-gray-700 leading-relaxed">
          <h2 className="text-xl font-semibold">Day-to-Day Bookkeeping</h2>
          <ul className="list-disc pl-6 space-y-1">
            <li>Recording income and expenses</li>
            <li>Reconciling bank and credit card accounts</li>
            <li>Maintaining general ledgers</li>
          </ul>

          <h2 className="text-xl font-semibold pt-4">Financial Reporting</h2>
          <ul className="list-disc pl-6 space-y-1">
            <li>Balance Sheets</li>
            <li>Profit & Loss Statements</li>
            <li>Cash Flow Reports</li>
          </ul>

          <h2 className="text-xl font-semibold pt-4">QuickBooks Expertise</h2>
          <ul className="list-disc pl-6 space-y-1">
            <li>Seamless setup and customization</li>
            <li>Efficient data entry and categorization</li>
            <li>Real-time financial tracking and reporting</li>
            <li>Troubleshooting and optimization</li>
          </ul>

          <h2 className="text-xl font-semibold pt-4">Year-End Preparation</h2>
          <ul className="list-disc pl-6 space-y-1">
            <li>Adjusting journal entries</li>
            <li>Trial balance review</li>
            <li>Coordination with tax preparers or auditors</li>
          </ul>
        </div>
      )
    }
  ];

  return (
    <div className="py-20 bg-gray-50" id="services">
      <h1 className="text-4xl font-bold text-center mb-10">Our Services</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 px-6">
        {services.map((service) => (
          <div
            key={service.id}
            className="p-6 bg-white rounded-xl shadow-md hover:shadow-xl transition cursor-pointer"
            onClick={() => setActiveModal(service.id)}
          >
            <h2 className="text-2xl font-semibold">{service.title}</h2>
          </div>
        ))}
      </div>

      <AnimatePresence>
        {activeModal && (
          <motion.div
            className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setActiveModal(null)}
          >
            <motion.div
              className="bg-white rounded-2xl shadow-xl max-w-xl w-full p-8"
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.8, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
            >
              <h2 className="text-2xl font-bold mb-4">
                {services.find((s) => s.id === activeModal)?.title}
              </h2>
              <div>{services.find((s) => s.id === activeModal)?.content}</div>

              <button
                onClick={() => setActiveModal(null)}
                className="mt-6 px-5 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
              >
                Close
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
